-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Vor- Nachteile von Unternehmensformen > Kapitalbeschaffung bei AG
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-AG durch den Verkauf von Aktien Kapital beschaffen?', 2, '[{"text": "Ja", "correct": true, "because": "Aktienverkauf ist eine Hauptmethode der Kapitalbeschaffung bei AGs"}, {"text": "Nein", "correct": false, "because": "Aktien sind ein zentrales Instrument"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kapitalbeschaffung einer IT-AG durch Aktien an der Börse möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Börsennotierte AGs können Aktien öffentlich verkaufen"}, {"text": "Nein", "correct": false, "because": "Börsenhandel ist für AGs üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert die Kapitalbeschaffung einer IT-AG durch Aktien eine Erhöhung des Grundkapitals?', 2, '[{"text": "Ja", "correct": true, "because": "Kapitalerhöhungen erhöhen das Grundkapital"}, {"text": "Nein", "correct": false, "because": "Kapitalerhöhung ist oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-AG durch die Ausgabe von Aktien ihre Unabhängigkeit von Bankkrediten erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Aktien reduzieren die Abhängigkeit von Fremdkapital"}, {"text": "Nein", "correct": false, "because": "Aktienfinanzierung stärkt Eigenkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kapitalbeschaffung einer IT-AG durch Aktien ohne Kosten verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Emissionskosten und Börsennotierung verursachen Kosten"}, {"text": "Ja", "correct": false, "because": "Es entstehen Emissionskosten"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptmethode der Kapitalbeschaffung einer IT-AG?', 2, '[{"text": "Ausgabe von Aktien", "correct": true, "because": "Aktien sind das primäre Instrument"}, {"text": "Bankkredite", "correct": false, "because": "Das ist Fremdkapital"}, {"text": "Staatliche Subventionen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzung ist für die Kapitalbeschaffung einer IT-AG durch Aktien an der Börse erforderlich?', 3, '[{"text": "Börsennotierung", "correct": true, "because": "Nur börsennotierte AGs können Aktien öffentlich handeln"}, {"text": "Mindestkapital von 25.000 Euro", "correct": false, "because": "AG benötigt 50.000 Euro"}, {"text": "Einzelgründung", "correct": false, "because": "Irrelevant für Aktien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für eine IT-AG durch Kapitalbeschaffung mit Aktien?', 3, '[{"text": "Hohe Flexibilität bei der Finanzierung", "correct": true, "because": "Aktien ermöglichen große Kapitalmengen"}, {"text": "Geringe Kosten", "correct": false, "because": "Emissionskosten sind hoch"}, {"text": "Keine Rückzahlung", "correct": false, "because": "Aktien sind Eigenkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gremium entscheidet über die Kapitalerhöhung einer IT-AG?', 2, '[{"text": "Hauptversammlung", "correct": true, "because": "Aktionäre entscheiden in der Hauptversammlung"}, {"text": "Vorstand", "correct": false, "because": "Vorstand schlägt vor, entscheidet nicht allein"}, {"text": "Aufsichtsrat", "correct": false, "because": "Aufsichtsrat kontrolliert, entscheidet nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil der Kapitalbeschaffung durch Aktien für eine IT-AG?', 3, '[{"text": "Verlust von Kontrolle durch neue Aktionäre", "correct": true, "because": "Neue Aktionäre können Einfluss nehmen"}, {"text": "Hohe Zinskosten", "correct": false, "because": "Keine Zinsen bei Aktien"}, {"text": "Einfache Durchführung", "correct": false, "because": "Komplex und kostenintensiv"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Kapitalbeschaffung durch Aktien für eine IT-AG?', 4, '[{"text": "Keine Rückzahlungspflicht", "correct": true, "because": "Aktien sind Eigenkapital"}, {"text": "Große Kapitalmengen möglich", "correct": true, "because": "Börse ermöglicht hohen Kapitalzufluss"}, {"text": "Kostengünstige Finanzierung", "correct": false, "because": "Emissionskosten sind hoch"}, {"text": "Unabhängigkeit von Banken", "correct": true, "because": "Reduziert Fremdkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die Kapitalbeschaffung durch Aktien für eine IT-AG?', 3, '[{"text": "Hohe Emissionskosten", "correct": true, "because": "Börsennotierung ist teuer"}, {"text": "Verlust von Kontrolle", "correct": true, "because": "Neue Aktionäre gewinnen Einfluss"}, {"text": "Keine Kapitalerhöhung möglich", "correct": false, "because": "Kapitalerhöhung ist möglich"}, {"text": "Abhängigkeit von Gläubigern", "correct": false, "because": "Aktien reduzieren Fremdkapital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind für die Kapitalbeschaffung einer IT-AG durch Aktien notwendig?', 4, '[{"text": "Beschluss der Hauptversammlung", "correct": true, "because": "Aktionäre entscheiden"}, {"text": "Börsennotierung", "correct": true, "because": "Für öffentlichen Handel erforderlich"}, {"text": "Keine Kapitalerhöhung", "correct": false, "because": "Kapitalerhöhung ist nötig"}, {"text": "Ausgabe neuer Aktien", "correct": true, "because": "Neue Aktien werden emittiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Kapitalbeschaffung einer IT-AG durch Aktien?', 3, '[{"text": "Aktienkurs", "correct": true, "because": "Kurs bestimmt Kapitalzufluss"}, {"text": "Marktbedingungen", "correct": true, "because": "Börsenlage beeinflusst Erfolg"}, {"text": "Produktionskosten", "correct": false, "because": "Wenig direkter Einfluss"}, {"text": "Investorinteresse", "correct": true, "because": "Nachfrage nach Aktien entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die Kapitalbeschaffung einer IT-AG von der einer GmbH?', 3, '[{"text": "AG nutzt Aktien, GmbH nicht", "correct": true, "because": "GmbH hat keine Aktien"}, {"text": "AG hat größere Kapitalmengen möglich", "correct": true, "because": "Börse bietet mehr Potenzial"}, {"text": "GmbH ist börsennotiert", "correct": false, "because": "Nur AG kann börsennotiert sein"}, {"text": "AG hat strengere Vorschriften", "correct": true, "because": "AktG ist strenger als GmbHG"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine IT-AG kann durch Aktien Kapital beschaffen. b) Die Kapitalbeschaffung durch Aktien ist kostenfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktien ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Kapitalbeschaffung durch Aktien erhöht das Grundkapital einer IT-AG. b) Eine IT-AG bleibt durch Aktien unabhängig von Banken.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Grundkapital steigt und Unabhängigkeit wird gefördert"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Hauptversammlung entscheidet über die Kapitalerhöhung einer IT-AG. b) Aktienfinanzierung führt zu hohen Zinskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hauptversammlung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kapitalbeschaffung durch Aktien kann die Kontrolle einer IT-AG beeinflussen. b) Eine IT-AG hat keine Emissionskosten bei Aktien.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrolle ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IT-AG kann durch Aktien große Kapitalmengen aufnehmen. b) Die Kapitalbeschaffung durch Aktien ist einfacher als bei einer GmbH.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Große Mengen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

